    readonly status: 'succeeded';
    readonly value: T;
} | {
    readonly status: 'failed';
    readonly error: unknown;
} | {
    readonly status: 'cancelled';
};

export interface ExecutionProgress {
    readonly completed: number;
    readonly total?: number;
    readonly message?: string;
}

export interface ExecutionRecord {
    readonly id: number;
    readonly label: string;
    readonly status: 'running' | 'cancelling' | 'succeeded' | 'failed' | 'cancelled';
    readonly startedAt: number;
    readonly finishedAt?: number;
    readonly cancelRequested: boolean;
    readonly progress?: ExecutionProgress;
}

export interface ExecutionSession {
    getSnapshot(): readonly ExecutionRecord[];
    subscribe(listener: () => void): () => void;
    run<T>(label: string, work: (context: ExecutionContext) => T | Promise<T>): Promise<ExecutionOutcome<T>>;
    cancel(): void;
    clearHistory(): void;
    close(): void;
}

export type FieldChange<TRecord extends Record<string, any> = Record<string, any>, K extends FieldKey<TRecord> = FieldKey<TRecord>> = {
    [P in K]: {
        readonly field: P;
        readonly label?: string;
        readonly before: TRecord[P] & SupportedPrimitive;
        readonly after: TRecord[P] & SupportedPrimitive;
        readonly reason?: string;
    };
}[K];

