export interface PolicyContext {
    documentType: string;
    role: string;
    amount?: number;
    currentStatus: string;
    targetStatus: string;
    data?: Record<string, unknown>;
}

export interface StatusTransition extends WorkflowTransition {
    label: string;
    description: string;
    icon: React.ReactNode;
    color: string;
}

export interface TransitionValidationResult {
    allowed: boolean;
    reason?: string;
}

export interface WorkflowActionDefinition extends WorkflowAction {
    label: string;
    description: string;
    icon: React.ReactNode;
    color: string;
}

export interface WorkflowContextType {
    getEngine: (workflowId: string) => WorkflowEngine;
}

WorkflowEngine: {
    new (config: import('@alneas/appkit-core/data').WorkflowDefinition<StatusTransition, WorkflowActionDefinition, WorkflowStatusInfo>): CoreWorkflowEngine<StatusTransition, WorkflowActionDefinition, WorkflowStatusInfo>;
}

export interface WorkflowPolicy<TContext> {
    validateTransition(context: TContext): TransitionValidationResult;
    requiresApproval(context: TContext): boolean;
    getRequiredFields(context: TContext): string[];
}

export declare class WorkflowPolicyEngine<TContext> {
    private policy;
    constructor(policy: WorkflowPolicy<TContext>);
    validateTransition(context: TContext): TransitionValidationResult;
    requiresApproval(context: TContext): boolean;
    getRequiredFields(context: TContext): string[];
}

export interface WorkflowProviderProps {
    configs: Record<string, WorkflowConfig>;
    children: React.ReactNode;
}

export interface WorkflowRegistry {
    [workflowId: string]: WorkflowConfig;
}

export interface WorkflowStatusInfo {
    title: string;
    description: string;
    nextSteps: string[];
    color: string;
    icon?: React.ReactNode;
}

export interface WorkflowStatusPanelProps {
    currentStatus: string;
    onAction?: (action: string) => void;
    actions: WorkflowActionDefinition[];
    statusInfoMap: Record<string, WorkflowStatusInfo>;
    defaultStatusInfo?: WorkflowStatusInfo;
    statusExtraContent?: Partial<Record<string, React.ReactNode>>;
    actionTitle?: string;
    requiredActionTitle?: string;
    requiredActionHint?: string;
}

